  green:  'rgba(55, 165, 70, 0.88)',   // 本物の緑(濃)→白文字
  blue:   'rgba(60, 125, 235, 0.90)',  // 本物の青(濃)→白文字
  purple: 'rgba(190, 130, 245, 0.50)',
