// v0.9.99977(俊克 pm10:41): 3状態循環トグル 💤保留 → 参照膜なし → 参照膜有り → 💤…
// 膜有り=説明文付きの点(参照膜)を持つグループ=本当の参照(説明書等)/膜なし=印だけの軽い用途/
// 保留💤=膜なしの一形態・特殊用途。カテゴリ別に復帰先を記憶(lastPlainGroup/lastDocGroup)。
// カテゴリが空なら次へスキップ(状況をステータスバーで通知)。
function refGroupsByCategory(doc, ref) {
  const points = collectRefPoints(doc).filter(p => !p.disabled); // v0.9.99981: 無効化は分類に含めない
  const map = new Map();
  for (const p of points) { const a = map.get(p.name) || []; a.push(p); map.set(p.name, a); }
  for (const n of Object.keys(ref.groups)) if (!map.has(n)) map.set(n, []);
  const plain = [], doclike = [];
  for (const [name, pts] of map) {
    const fam = pts.length ? pts[0].fam : (Number(ref.groups[name]) || 1);
    if (isPendingFam(fam)) continue; // 保留は💤カテゴリ
    (pts.some(q => q.desc) ? doclike : plain).push(name);
  }
  return { plain, doclike, hasPending: points.some(p => isPendingFam(p.fam)) || Object.keys(ref.groups).some(n => isPendingFam(ref.groups[n])) };
}
async function referenceToggleMode(editor) {
  if (!editor) return;
  const doc = editor.document;
  const ref = getRefMeta(doc);
  const cats = refGroupsByCategory(doc, ref);
  const cur = (ref.activeGroup || ref.issueGroup || '');
  let mode = 'pending';
  if (cur && cur !== '💤') mode = cats.doclike.includes(cur) ? 'doc' : 'plain';
  const order = ['pending', 'plain', 'doc'];
  let next = mode, hops = 0, name = '';
  while (hops < 3) {
    next = order[(order.indexOf(next) + 1) % order.length];
    hops++;
    if (next === 'pending') { name = '💤'; break; } // 💤はグループ未作成でも選べる(初回発行で自動作成)
    const pool = next === 'plain' ? cats.plain : cats.doclike;
    const last = next === 'plain' ? ref.lastPlainGroup : ref.lastDocGroup;
    if (pool.length) { name = (last && pool.includes(last)) ? last : pool[0]; break; }
  }
  if (!name) { vscode.window.setStatusBarMessage('No reference groups — create via Edit ▾ → Reference', 3000); return; }
  if (name === '💤') {
    if (cur && cur !== '💤') { if (cats.doclike.includes(cur)) ref.lastDocGroup = cur; else ref.lastPlainGroup = cur; }
    ref.activeGroup = '💤';
  } else {
    ref.activeGroup = name;
    ref.issueGroup = name;
    if (next === 'plain') ref.lastPlainGroup = name; else ref.lastDocGroup = name;
  }
  restoreRefFront(doc, ref); // v1.0.8(俊克 バグ1): 切替先グループの最前線Fを復元
  await saveRefMeta(doc, ref);
  postBookmarkState(editor);
  const modeLabel = name === '💤' ? '💤 Pending group' : (next === 'doc' ? 'Annotated: ' + name : 'Marks: ' + name);
  vscode.window.setStatusBarMessage('Working reference: ' + modeLabel, 2500);
}
// v0.9.99986(俊克ひらめき 7/5 眼科): 3セグメントトグルの「クリックした位置=目的のモード」を直接セット
// (循環でなく直行)。💤保留/膜なし/膜有りのどれをクリックしたかで判定。メニューは閉じない(webview側)。
async function referenceSetMode(editor, mode) {
  if (!editor) return;
  const doc = editor.document;
  const ref = getRefMeta(doc);
  const cats = refGroupsByCategory(doc, ref);
  const cur = (ref.activeGroup || ref.issueGroup || '');
  if (mode === 'pending') {
    if (cur && cur !== '💤') { if (cats.doclike.includes(cur)) ref.lastDocGroup = cur; else ref.lastPlainGroup = cur; }
    ref.activeGroup = '💤';
  } else {
    const pool = mode === 'plain' ? cats.plain : cats.doclike;
    const last = mode === 'plain' ? ref.lastPlainGroup : ref.lastDocGroup;
    const name = (last && pool.includes(last)) ? last : (pool[0] || '');
    if (!name) { vscode.window.setStatusBarMessage('No ' + (mode === 'doc' ? 'annotated' : 'marks-only') + ' reference groups — create via Edit ▾ → Reference', 3000); return; }
    ref.activeGroup = name;
    ref.issueGroup = name;
    if (mode === 'plain') ref.lastPlainGroup = name; else ref.lastDocGroup = name;
  }
  restoreRefFront(doc, ref); // v1.0.8(俊克 バグ1): 切替先グループの最前線Fを復元
  await saveRefMeta(doc, ref);
  postBookmarkState(editor);
}
// v0.9.999100(俊克): Me Dock参照パネルからのグループ作成。QuickPickの代わり=記号/カスタム/名前/説明をパラメータで受ける。
// v0.9.999106(俊克): カーソル位置の参照符を返す(編集モード用)。無ければnull。
function refMarkAtCursor(editor) {
  if (!editor) return null;
  const doc = editor.document;
  const sel = editor.selection.active; const line = sel.line, ch = sel.character;
  if (line < 0 || line >= doc.lineCount) return null;
  const text = doc.lineAt(line).text || '';
  if (!lineHasRefMark(text)) return null;
  REF_POINT_RE.lastIndex = 0; let m;
  while ((m = REF_POINT_RE.exec(text)) !== null) {
    const start = m.index, end = m.index + m[0].length;
    if (ch >= start && ch <= end) {
      const disabled = (m[1] === REF_MARK_DISABLED);
      const fam = (m[2] === 'P') ? 'P' : Number(m[2]);
      const pp = parseRefPointInner(m[3]);
      return { line, start, end, fam, disabled, name: pp.name, base: pp.base, ts: pp.ts, desc: pp.desc };
    }
  }
  return null;
}
// v0.9.999106(俊克): 参照グループを一括更新。名前・記号=全符(名前でグループが束ねられている=固有名詞)、
// 説明=そのグループの1つの説明(説明を持つ符=holderを更新・無ければ先頭符に付与)。各符のマーカー(▶◀/▷◁)は保持。
async function referenceUpdateGroup(editor, origName, newFamRaw, newName, newDesc, customGlyph) {
  if (!editor) return;
  const doc = editor.document;
  const ref = getRefMeta(doc);
  const newFam = (newFamRaw === 'P') ? 'P' : Number(newFamRaw);
  const nm = String(newName || '').trim();
  if (!nm) { vscode.window.showWarningMessage('Reference: グループ名を入力してください'); return; }
  if (nm.includes('//') || nm.includes('*}') || nm.includes('{*')) { vscode.window.showWarningMessage('Reference: 「//」「{*」「*}」は名前に使えません'); return; }
  const marks = collectRefPoints(doc).filter(q => q.name === origName);
  if (!marks.length) { vscode.window.setStatusBarMessage('Reference: 対象の参照符が見つかりません', 2500); return; }
  const nd = String(newDesc || '').trim();
  let holder = marks.find(q => q.desc) || marks[0]; // 説明の受け皿(既存の説明持ち・無ければ先頭)
  const we = new vscode.WorkspaceEdit();
  // 位置ズレを避けるため、後ろの符から書き換える(行降順・同一行は開始位置降順)。
  const sorted = marks.slice().sort((a, b) => (b.line - a.line) || (b.start - a.start));
  for (const mk of sorted) {
    const marker = mk.disabled ? REF_MARK_DISABLED : REF_MARK_ACTIVE;
    const isHolder = (mk.line === holder.line && mk.start === holder.start);
    const dsc = isHolder ? nd : (mk.desc || '');
    const core = '{* ' + marker + 'mR' + newFam + '=' + nm + (dsc ? ' // ' + dsc : '') + ' *}';
    we.replace(doc.uri, new vscode.Range(mk.line, mk.start, mk.line, mk.end), wrapRefMark(doc, core));
  }
  await vscode.workspace.applyEdit(we);
  // mMETA: グループ名が変わったら付け替え・記号(fam)更新・F/作業グループも追従
  if (origName !== nm) {
    if (ref.groups[origName] !== undefined) delete ref.groups[origName];
    if (ref.activeGroup === origName) ref.activeGroup = nm;
    if (ref.issueGroup === origName) ref.issueGroup = nm;
    if (ref.lastPlainGroup === origName) ref.lastPlainGroup = nm;
    if (ref.lastDocGroup === origName) ref.lastDocGroup = nm;
    if (ref.front && ref.front.name === origName) ref.front.name = nm;
  }
  ref.groups[nm] = newFam;
  const cg = String(customGlyph || '').trim(); // R6〜9のカスタム記号(mMETA随伴)
  if (newFam >= 8 && newFam <= 9 && cg) { if (!ref.symbols) ref.symbols = {}; ref.symbols[newFam] = cg; }
  await saveRefMeta(doc, ref);
  refresh(editor);
  postBookmarkState(editor);
  vscode.window.setStatusBarMessage('Reference: ' + refFamilySymbol(newFam, ref.symbols) + ' 「' + nm + '」を更新しました(' + marks.length + '符)', 3500);
}
async function referenceCreateFromPanel(editor, famRaw, base, desc, customGlyph) {
  if (!editor) return;
  const doc = editor.document;
  const ref = getRefMeta(doc);
  const fam = Number(famRaw);
  if (!(fam >= 1 && fam <= 9)) { vscode.window.showWarningMessage('Reference: 記号を選択してください'); return; }
  const name = String(base || '').trim();
  if (!name) { vscode.window.showWarningMessage('Reference: グループ名を入力してください'); return; }
  if (name.includes('//') || name.includes('*}') || name.includes('{*')) { vscode.window.showWarningMessage('Reference: 「//」「{*」「*}」は名前に使えません'); return; }
  if (refGroupCount(doc, ref) >= REF_GROUP_MAX) { vscode.window.showWarningMessage('参照グループは最大' + REF_GROUP_MAX + '個です(R1〜R9)。▾メニューから不要なグループを削除してください。'); return; }
  // カスタム記号(R8〜9)をmMETAに保存(R1〜7は既定記号)
  const cg = String(customGlyph || '').trim();
  if (fam >= 8 && fam <= 9 && cg) { if (!ref.symbols) ref.symbols = {}; ref.symbols[fam] = cg; }
  const groupName = name; // v0.9.999101: 名前はパネルでタイムスタンプ付き済み(二重付与しない)
  const d = String(desc || '').trim();
  const snippet = wrapRefMark(doc, '{* ▶◀mR' + fam + '=' + groupName + (d ? ' // ' + d : '') + ' *}');
  const pos = editor.selection.active;
  const we = new vscode.WorkspaceEdit();
  we.insert(doc.uri, pos, snippet);
  await vscode.workspace.applyEdit(we);
  ref.groups[groupName] = fam;
  ref.lastFam = fam;
  ref.front = { name: groupName, ord: 0 };
  ref.activeGroup = groupName;
  ref.issueGroup = groupName;
  await saveRefMeta(doc, ref);
  refresh(editor);
  postBookmarkState(editor);
  vscode.window.setStatusBarMessage('Reference: ' + refFamilySymbol(fam, ref.symbols) + ' グループ「' + groupName + '」を作成しました', 4000);
}
// v0.9.99968: ★参照膜プロジェクト段3 — Reference Me(参照グループ作成)。Edit Meプルダウンから起動。
// 手順(1)create: 記号ピッカー(前回記号=mMETA随伴記憶)→名前入力→説明(任意)→カーソル位置に点膜を挿入。
// 名前+TS=グループID。記号ピッカーは「正準記号を強制しグループ化を成立させる」本質機能(記号ブレ=分裂防止)。
// 1膜1グループ=同一膜(レキシカルスコープ・小膜/孫膜は別グループ可)に既存グループがあれば警告。
// 打った符がその場でF(💤駐車と同じ)=段4の巡回起点としてref.frontへ。
async function referenceMeCreate() {
  const editor = getMeDockTargetEditor() || vscode.window.activeTextEditor;
  if (!editor) { vscode.window.showInformationMessage('Reference Me: 対象のエディタがありません。'); return; }
  const doc = editor.document;
  const ref = getRefMeta(doc);
  // v0.9.99997(俊克改良1): 保留(💤)はReference Meで作らない=唯一の特別枠。記号ピッカーは通常記号のみ(※†‡*§)。
  // 保留は⇄トグルで選び💤発行するだけ=常に単一の保留グループ(保留符は互いに無関係・ただ「保留」の意味だけ共有)。
  const famItems = Object.keys(REF_FAMILY_SYMBOLS).filter(k => !isPendingFam(k)).map(k => ({
    label: REF_FAMILY_SYMBOLS[k] + '  (R' + k + ')',
    description: k === '1' ? '日本式・既定' : '',
    fam: Number(k)
  }));
  const lastIdx = famItems.findIndex(it => it.fam === Number(ref.lastFam));
  if (lastIdx > 0) famItems.unshift(famItems.splice(lastIdx, 1)[0]); // 前回の記号を先頭に(mMETA記憶)
  const famPick = await vscode.window.showQuickPick(famItems, { placeHolder: 'Reference Me: 参照記号を選択(R族=見た目の族。グループとは独立)' });
  if (!famPick) return;
  const base = await vscode.window.showInputBox({
    prompt: 'Reference Me: 参照グループ名(名前+タイムスタンプがグループIDになります)',
    value: '参照',
    validateInput: (v) => {
      const s = String(v || '').trim();
      if (!s) return '名前を入力してください';
      if (s.includes('//') || s.includes('*}') || s.includes('{*')) return '「//」「{*」「*}」は名前に使えません';
      return null;
    }
  });
  if (base === undefined) return;
  const desc = await vscode.window.showInputBox({ prompt: 'Reference Me: この参照符の説明文(任意・Enterでスキップ)' });
  if (desc === undefined) return;
  // v0.9.99973/99995: 上限は通常グループのみ(max10)。保留(💤=R9)は別枠なので上限対象外。
  if (!isPendingFam(famPick.fam) && refGroupCount(doc, ref) >= REF_GROUP_MAX) {
    vscode.window.showWarningMessage('参照グループは最大' + REF_GROUP_MAX + '個です。▾メニューから不要なグループを削除してください。');
    return;
  }
  const stamp = getDefaultMembraneName().replace(/^name_/, '');
  const groupName = String(base).trim() + '_' + stamp;
  const pos = editor.selection.active;
  const snippet = wrapRefMark(doc, '{* ▶◀mR' + famPick.fam + '=' + groupName + (String(desc).trim() ? ' // ' + String(desc).trim() : '') + ' *}'); // v0.9.99993: コメント包み
  const we = new vscode.WorkspaceEdit();
  we.insert(doc.uri, pos, snippet);
  await vscode.workspace.applyEdit(we);
  ref.groups[groupName] = famPick.fam;
  ref.lastFam = famPick.fam;
  ref.front = { name: groupName, ord: 0 }; // 打った符がその場でF(駐車と同じ・ord=グループ内文書順)
  ref.activeGroup = isPendingFam(famPick.fam) ? '💤' : groupName; // v0.9.99972: 作成したグループを作業グループに
  ref.issueGroup = groupName;
  await saveRefMeta(doc, ref);
  refresh(editor);
  postBookmarkState(editor);
  vscode.window.setStatusBarMessage('Reference Me: ' + refFamilySymbol(famPick.fam) + ' グループ「' + groupName + '」を作成しました', 4000);
}
