const REAL_GREEN_BUTTON = '🟢';
const REAL_RED_BUTTON = '🔴';
const REAL_BUTTON_RE = /[🟢🔴]/gu;
// v0.9.470: sRJF marker migrated from inline HTML span to end-of-line comment.
