function formatRealButtonZone(buttons) {
  const out = [];
  if (buttons.has(REAL_GREEN_BUTTON)) out.push(REAL_GREEN_BUTTON);
  if (buttons.has(REAL_RED_BUTTON)) out.push(REAL_RED_BUTTON);
  return out.length ? ' ' + out.join(' ') : '';
}

