  if (!sel || !sel.isEmpty) return;
  const pos = sel.active;
  const text = editor.document.lineAt(pos.line).text || '';

  // Only act on membrane open lines (close lines are short, rarely wrap).
  const parts = membraneLineParts(text, 'open');
