// {* ▼mCN=0865_RENAME_ME // v0.9.235 Rename Me safe implementation (📊⊕0+0D0W) [oGJF=h] [tRJF=h] *}
function membraneNameRangeForRenameOnLine(document, line, expectedKind, expectedId) {
  if (!document || line < 0 || line >= document.lineCount) return null;
  const rawLine = document.lineAt(line).text || "";
  const raw = normalizeProtoMembraneLineText(rawLine);
  const unwrapped = unwrapMembraneCommentText(raw || "");
  const text = unwrapped.inner || raw;
  const arrow = expectedKind === 'open' ? '[▼▽]' : '[▲△]';
  const key = '(?:mCN|CN|H1|H2|H3)';

  // Code / proto source:
  //   // {* ▼mCN=name // comment *}
  //   // {* ▼H1=name // comment *}
  let re = new RegExp('^(\\s*)(//[ \\t]*\\{[ \\t]*' + arrow + '[ \\t]*' + key + '[ \\t]*=[ \\t]*)([^\\r\\n]*?)(?=[ \\t]+\\/\\/|[ \\t]*\\*?\\}\\s*$|$)(.*)$');
  let m = text.match(re);

  // Markdown hidden comments:
  //   [//]: # (▼name // comment)
  //   [//]: # (▼mCN=name // comment)
  //   [//]: # (▼H1=name // comment)
  if (!m) {
    re = new RegExp('^(\\s*)(\\[\\/\\/\\]:[ \\t]*#[ \\t]*(?:(?:\\"|\\()[ \\t]*)?' + arrow + '[ \\t]*(?:' + key + '[ \\t]*=[ \\t]*)?)([^\\r\\n]*?)(?=[ \\t]+\\/\\/|[ \\t]*[\\")]|$)(.*)$');
    m = text.match(re);
  }

  if (!m) return null;

  const idText = cleanMembraneName(m[3]);
  if (!idText) return null;
  if (expectedId !== undefined && idText !== expectedId) return null;

  let idStart = m[1].length + m[2].length;
  let idEnd = idStart + idText.length;

  // Map back to the raw source line if proto normalization changed positions.
  const rawIdStart = rawLine.indexOf(idText);
  if (rawIdStart >= 0) {
    idStart = rawIdStart;
    idEnd = rawIdStart + idText.length;
  }

  return {
    id: idText,
    range: new vscode.Range(line, idStart, line, idEnd)
  };
}

function currentMembranePairForRename(editor) {
  if (!editor) return null;
  const doc = editor.document;
  const line = editor.selection.active.line;

  const info = membraneLineInfo(doc, line);
  if (info) {
    const pair = collectPairs(doc, { excludeIndex: false }).find(p => {
      if (info.kind === 'open') return p.start === info.line && p.id === info.id;
      return p.end === info.line && p.id === info.id;
    });
    if (pair) return pair;
  }

  return findCurrentPair(editor);
}

async function renameMe() {
  const editor = vscode.window.activeTextEditor;
  if (!editor) return;

  const pair = currentMembranePairForRename(editor);
  if (!pair) {
    vscode.window.showInformationMessage('Rename Me: put the cursor inside a membrane or on its name.');
    return;
  }

  const openName = membraneNameRangeForRenameOnLine(editor.document, pair.start, 'open', pair.id);
  const closeName = membraneNameRangeForRenameOnLine(editor.document, pair.end, 'close', pair.id);
  if (!openName || !closeName) {
    vscode.window.showWarningMessage('Rename Me: matching start/end membrane name range was not found.');
    return;
  }

  const nextNameInput = await vscode.window.showInputBox({
    title: 'Rename Me',
    prompt: 'Rename this Me. Start and end membrane names will be updated together.',
    value: pair.id,
    placeHolder: 'Example: My First Me_105844.503 / 私 第一膜_105844.503'
  });
  if (nextNameInput === undefined) return;

  const nextName = normalizeMembraneId(nextNameInput);
  if (!nextName) {
    vscode.window.showWarningMessage('Rename Me: membrane name cannot be empty.');
    return;
  }
  if (nextName === pair.id) return;

  const ok = await editor.edit(edit => {
    edit.replace(closeName.range, nextName);
    edit.replace(openName.range, nextName);
  }, { undoStopBefore: true, undoStopAfter: true });

  if (ok) {
    // v0.9.387: put the cursor on the actual newly-created opener line.
    const insertedLeadingBlank = !hasSelection && startLine > 0 && !isBlankDocumentLine(doc, startLine - 1);
    const openerLineNo = hasSelection ? startLine : startLine + (insertedLeadingBlank ? 1 : 0);
    editor.selection = new vscode.Selection(openerLineNo, indent.length, openerLineNo, indent.length);
    editor.revealRange(new vscode.Range(openerLineNo, 0, openerLineNo, 0), vscode.TextEditorRevealType.InCenterIfOutsideViewport);
    if (meDockPanel) meDockPanel.webview.postMessage({ type: 'setLineValue', value: String(openerLineNo + 1) });
    setTimeout(() => { refresh(editor); ensureMembraneMstatMetadata(editor); if (meDockPanel) meDockPanel.webview.postMessage({ type: 'setLineValue', value: String(openerLineNo + 1) }); }, 80);
  }
}
// {* ▲mCN=0865_RENAME_ME // end [cGJF=h] *}



// {* ▼mCN=0867_ME_DOCK_CURRENT_LINE_MARKER // v0.9.253 Me Dock current line marker (📊⊕0+0D0W) [oGJF=h] [tRJF=h] *}
function ensureMeDockCurrentLineDecoration() {
  if (meDockCurrentLineDecoration) return meDockCurrentLineDecoration;
  // v0.9.940: 現在行マーカーを左ガターのSVG矢印に(俊克 6/17)。膜縦線はcomputeGutterLaneDecorationsが
  //   現在行を1行スキップする(栞と同じ"貫く"流儀)のでマーカーが上書きされない。
  const opts = {
    rangeBehavior: vscode.DecorationRangeBehavior.ClosedClosed,
    overviewRulerColor: 'rgba(255, 170, 0, 0.95)',
    overviewRulerLane: vscode.OverviewRulerLane.Right,
    gutterIconSize: 'contain'
  };
  try { if (extensionContext && extensionContext.extensionUri) opts.gutterIconPath = vscode.Uri.joinPath(extensionContext.extensionUri, 'current-line.svg'); } catch (_) {}
  if (!opts.gutterIconPath) opts.after = { contentText: ' \u21e6', color: 'rgba(255, 120, 0, 1)', fontWeight: 'bold', margin: '0 0 0 6px' };
  meDockCurrentLineDecoration = vscode.window.createTextEditorDecorationType(opts);
  return meDockCurrentLineDecoration;
}

function ensureMeDockCurrentLineHoverDecoration() {
  if (meDockCurrentLineHoverDecoration) return meDockCurrentLineHoverDecoration;
  meDockCurrentLineHoverDecoration = vscode.window.createTextEditorDecorationType({ isWholeLine: true }); // v0.9.947: 視覚なし・行全体でホバー可(空行/短行でもメニューが出る)
  return meDockCurrentLineHoverDecoration;
}
// v0.9.946: H-TOCジャンプの飛び先keyを帰還リングへ(最新先頭・重複排除・最大2・URI付き)。
function pushHtocReturn(key, uri) {
  const k = String(key || "").trim();
  if (!k) return;
  const u = String(uri || "");
  _htocReturnRing = _htocReturnRing.filter(e => !(e.key === k && e.uri === u));
  _htocReturnRing.unshift({ key: k, uri: u });
  if (_htocReturnRing.length > 2) _htocReturnRing.length = 2;
}
// v0.9.946: 現在行ホバーの帰還メニュー(📍現在地 + ↩直近H-TOC最大2件・現在膜と同keyは除外)。
function buildHtocReturnMenu(editor) {
  if (!editor || !editor.document) return null;
  const uri = editor.document.uri.toString();
  const line = (editor.selection && editor.selection.active) ? editor.selection.active.line : 0;
  let curKey = "";
  try { const cp = findCurrentPair(editor); if (cp) curKey = String(cp.id || "").trim(); } catch (_) {}
  const ringKeys = _htocReturnRing.filter(e => e.uri === uri).map(e => e.key);
  // v0.9.949: 現在膜がH-TOCリングに無い(=無関係な作業場所)なら、作業位置anchorを現在地に更新(最後に居た行)。
  //   H-TOC膜の中を動いても更新しない=俊克の但し書き。
  if (!(curKey && ringKeys.indexOf(curKey) >= 0)) { _htocAnchor = { uri: uri, line: line }; }
  const targets = _htocReturnRing.filter(e => e.uri === uri && e.key && e.key !== curKey).slice(0, 2);
  const showAnchor = !!(_htocAnchor && _htocAnchor.uri === uri && _htocAnchor.line !== line);
  if (!targets.length && !showAnchor) return null;
  let body = "\uD83E\uDDED H-TOC \u3078\u623b\u308b  \n\uD83D\uDCCD Ln " + (line + 1) + "  \n";
  if (showAnchor) {
    const aArg = encodeURIComponent(JSON.stringify([_htocAnchor.line]));
    body += "[\u21a9 Ln " + (_htocAnchor.line + 1) + "\uFF08\u4f5c\u696d\u4f4d\u7f6e\uFF09](command:lai-membrane.htocReturnLine?" + aArg + ")  \n";
  }
  targets.forEach(e => {
    const arg = encodeURIComponent(JSON.stringify([e.key]));
    body += "[\u21a9 " + e.key + "](command:lai-membrane.htocReturn?" + arg + ")  \n";
  });
  const md = new vscode.MarkdownString(body);
  md.isTrusted = { enabledCommands: ["lai-membrane.htocReturn", "lai-membrane.htocReturnLine"] };
  return md;
}
function updateMeDockCurrentLineMarker() {
  const editor = getMeDockTargetEditor ? getMeDockTargetEditor() : vscode.window.activeTextEditor;
  if (!meDockPanel || !editor || !meDockCurrentLineMarkerActive) {
    clearMeDockCurrentLineMarker();
    return;
  }
  const pos = editor.selection.active;
  if (!pos || pos.line < 0 || pos.line >= editor.document.lineCount) {
    clearMeDockCurrentLineMarker();
    return;
  }
  const range = new vscode.Range(pos.line, 0, pos.line, 0); // v0.9.940: 栞と同じ点レンジ
  const md = buildHtocReturnMenu(editor);
  const eol = editor.document.lineAt(pos.line).text.length;
  const hov = ensureMeDockCurrentLineHoverDecoration();
  // v0.9.950: ホバーは行の状態で「厳密に片方だけ」に載せ重複回避(俊克 6/18: 両方=2重・矢印だけ=微妙)。
  //   文字のある行→行テキスト側(行全体ホバー=どこでも楽に出る)。空行→ガター矢印(テキスト無くホバー判定が乗らないため)。
  if (md && eol === 0) {
    editor.setDecorations(ensureMeDockCurrentLineDecoration(), [{ range, hoverMessage: md }]);
    editor.setDecorations(hov, []);
  } else {
    editor.setDecorations(ensureMeDockCurrentLineDecoration(), [range]);
    if (md) editor.setDecorations(hov, [{ range: new vscode.Range(pos.line, 0, pos.line, Math.max(1, eol)), hoverMessage: md }]);
    else editor.setDecorations(hov, []);
  }
}

function clearMeDockCurrentLineMarker() {
  const editor = getMeDockTargetEditor ? getMeDockTargetEditor() : vscode.window.activeTextEditor;
  if (meDockCurrentLineDecoration && editor) editor.setDecorations(meDockCurrentLineDecoration, []);
  if (meDockCurrentLineHoverDecoration && editor) editor.setDecorations(meDockCurrentLineHoverDecoration, []);
}
// {* ▲mCN=0867_ME_DOCK_CURRENT_LINE_MARKER // end [cGJF=h] *}

// {* ▼mCN=0866_INLINE_NEW_RENAME // v0.9.242 inline Me Dock New/Rename helpers (📊⊕0+0D0W) [oGJF=h] [tRJF=h] *}
function getMeDockTargetEditor() {
  return meDockTargetEditor || vscode.window.activeTextEditor;
}

// v0.9.707: Me Dock の書式ボタン挿入。選択テキストを記法で包んで初期値付きで挿入し、本文を選択状態にする
// (プレースホルダを即上書きできる)。kind: 'highlight' | 'strike' | 'heading'。
//   highlight → =={本文(赤/黄)//tip}==      (文字色赤・背景黄・コメントtip)
//   strike    → ~~{本文(赤/)//tip}~~       (線色赤・背景は薄ピンク自動・コメントtip)
//   heading   → ##[本文(白/緑)//tip]##      (H2・白文字・緑背景・コメントtip。行頭でないと効かないため現在行を包む)
// v0.9.877: C系ブロックコメント /* … */ を持つ言語。これらでは書式ボタンの出力を /* … */ で包む
// (コメント包み記法 → コードから見れば ただのコメント、MeOS上では装飾だけが見える)。markdown/
// plaintext 等の非該当言語は素の MeOS 記法のまま出力する。俊克 6/15 am10:33。
const MEOS_BLOCK_COMMENT_LANGS = new Set(['javascript', 'javascriptreact', 'typescript', 'typescriptreact', 'jsonc', 'c', 'cpp', 'csharp', 'java', 'go', 'rust', 'php', 'swift', 'kotlin', 'scala', 'dart', 'css', 'scss', 'less', 'objective-c', 'objective-cpp']);
// v0.9.933: 見出し等のタイムスタンプ。YYYY.MM.DD(曜日1字)+ am/pm先頭(俊克: pmは区切りとして前に) + HH:MM.SS。曜日=S-M-T-W-t-F-s。
function meosFormatStamp(d) {
  const p = n => String(n).padStart(2, '0');
  const wd = ['S', 'M', 'T', 'W', 't', 'F', 's'][d.getDay()];
  let h = d.getHours();
  const ap = h < 12 ? 'am' : 'pm';
  h = h % 12; if (h === 0) h = 12;
  return d.getFullYear() + '.' + p(d.getMonth() + 1) + '.' + p(d.getDate()) + '(' + wd + ')' + ap + p(h) + ':' + p(d.getMinutes()) + '.' + p(d.getSeconds());
}
async function insertFormatTemplate(kind, editor, fg, bg, level) {
  if (!editor) return;
  const doc = editor.document;
  const sel = editor.selection;
  const selText = sel.isEmpty ? '' : doc.getText(sel);
  // v0.9.877: ファイル形式を認識して出力を変える。C系コメント言語なら装飾を /* … */ で包む。
  const wrap = MEOS_BLOCK_COMMENT_LANGS.has(doc.languageId);
  const cOpen = wrap ? '/* ' : '';
  const cClose = wrap ? ' */' : '';
  // v0.9.879: 文字色(fg)/背景色(bg)はFormatの「V」カラーピッカーで選ぶ。未指定は種別ごとの既定色。
  const def = (kind === 'heading') ? { fg: '白', bg: 'Green' } : (kind === 'strike') ? { fg: '赤', bg: '' } : { fg: '赤', bg: '黄' };
  const FG = (fg && String(fg).trim()) ? String(fg).trim() : def.fg;
  const BG = (typeof bg === 'string') ? bg.trim() : def.bg;
  const spec = '(' + FG + '/' + BG + ')//[]tip=';
  let bodySel; // 挿入後に選択する本文(プレースホルダ)範囲
  if (kind === 'heading') {
    // 見出しは行頭でなければレンダリングされない → 現在行全体を見出しで包む(本文=選択 or 行内容 or 既定)。
    // v0.9.936: 作成日時は「本文末尾に可視」で入れる(俊克 6/17: //コメントだと隠れて見えない)。
    //   見出し本文 = テキスト + ' ' + タイムスタンプ。コメントは空 //[]tip= に戻す。
    //   本文中の (W) は parseColorSpec が色無効＆直後が行末でないため温存される(末尾の(白/green)だけが色)。
    const stamp = meosFormatStamp(new Date());
    const bgEn = normalizeBgColor(BG) || BG; // v0.9.935: bgは英語小文字=日英混在表示
    const hspec = '(' + FG + '/' + bgEn + ')//[]tip=';
    const ln = sel.active.line;
    const lineText = doc.lineAt(ln).text;
    const body = (selText && selText.indexOf('\n') < 0) ? selText : (lineText.trim() || 'Heading');
    const visibleBody = body + ' ' + stamp; // 本文 + 可視タイムスタンプ
    const hashes = '#'.repeat(Math.max(1, Math.min(3, Number(level) || 2))); // v0.9.99936: ↻でH1/H2/H3を選んで挿入
    const newText = cOpen + hashes + '[ ' + visibleBody + ' ' + hspec + ']' + hashes + cClose; // v0.9.99963: 見出し本文の左右にも半角スペースpadding
    await editor.edit(eb => eb.replace(doc.lineAt(ln).range, newText));
    const b = cOpen.length + hashes.length + 2; // #{1,3}[ + 左padding空白 の直後
    bodySel = new vscode.Selection(new vscode.Position(ln, b), new vscode.Position(ln, b)); // v0.9.999132: 見出しは選択しない(適用後カーソルが見出し内→⊘##表示)は残る
  } else {
    let prefix, close, defBody;
    if (kind === 'highlight') { prefix = '=={'; close = '}=='; defBody = 'ハイライト'; }
    else if (kind === 'strike') { prefix = '~~{'; close = '}~~'; defBody = '取消線'; }
    else return;
    const body = selText || defBody;
    const startOff = doc.offsetAt(sel.start);
    // v0.9.885: C系言語では「分割方式」で出力(本文=実コードのまま動く)。全体包みが欲しければ中の */ /* を消すだけ(俊克 6/15 pm08:50)。
    const openPart = wrap ? ('/* ' + prefix + ' */ ') : prefix;
    const tailPart = wrap ? (' /* ' + spec + close + ' */') : (spec + close);
    // v0.9.99963: prose の ==/~~ は本文の左右に半角スペースを入れる(俊克 7/1 pm12:52)=背景色が連続する"真の"左右padding。
    //   嫌なら手で消せる。code(split方式)は本文=実コードなのでpad無し。
    const pad = wrap ? '' : ' ';
    await editor.edit(eb => eb.replace(sel, openPart + pad + body + pad + tailPart));
    const b = startOff + openPart.length + pad.length;
    bodySel = new vscode.Selection(doc.positionAt(b), doc.positionAt(b + body.length));
  }
  // v0.9.714: 挿入後、エディタにフォーカスを移し、本文(プレースホルダ)を選択状態にする(即上書きで書き込めるように)。
  // 俊克 am11:15「ボタンを押した後エディタにフォーカスを移して」。focusMeDockTargetEditorは選択を1点に潰すので使わない。
  editor.selection = bodySel;
  await vscode.window.showTextDocument(doc, { viewColumn: editor.viewColumn, preserveFocus: false, selection: bodySel });
}

// v0.9.999124(俊克): Formatの文脈トグル。選択が空でカーソルが既存装飾の中なら、その装飾を「解除」する。
// 検出=行内の =={…}== / ~~{…}~~、または行頭見出し ##[…]##。本文は parseColorSpec で色スペックを剥がして取り出す。
// 解除後、ハイライト/取消線は本文範囲を選択で返す(範囲を失わず即再装飾可)。見出しは行が対象なので選択不要。
function formatSpanAtCursor(editor, kind) {
  if (!editor) return null;
  const doc = editor.document;
  const pos = editor.selection.active;
  const line = pos.line;
  const text = doc.lineAt(line).text || '';
  if (kind === 'heading') {
    const m = text.match(MARK_HEADING_RE);
    if (!m) return null;
    const hs = m[0].indexOf('#'); if (hs < 0) return null;
    const openBr = m[0].indexOf('['), closeBr = m[0].lastIndexOf(']');
    if (openBr < 0 || closeBr <= openBr) return null;
    const inner = m[0].slice(openBr + 1, closeBr);
    const body = String(parseColorSpec(inner, 'fg', inner).bodyText || inner).trim();
    return { kind, range: new vscode.Range(line, hs, line, m[0].length), body };
  }
  const re = (kind === 'highlight') ? /=={[^\n]*?}==/g : (kind === 'strike') ? /~~\{[^\n]*?\}~~/g : null;
  if (!re) return null;
  let m; re.lastIndex = 0;
  while ((m = re.exec(text)) !== null) {
    const s = m.index, e = m.index + m[0].length;
    if (pos.character >= s && pos.character <= e) {
      const inner = m[0].slice(3, m[0].length - 3); // =={ / }== ・ ~~{ / }~~ を剥がす
      const body = String(parseColorSpec(inner, 'fg', inner).bodyText || inner).trim();
      return { kind, range: new vscode.Range(line, s, line, e), body };
    }
  }
  return null;
}
async function removeFormatAtCursor(editor, span) {
  if (!editor || !span) return;
  const doc = editor.document;
  // v0.9.999126(俊克 改良2): 見出しは本文末尾に可視タイムスタンプが付く→解除時に一緒に消す。
  if (span.kind === 'heading') {
    span.body = span.body.replace(/\s*\d{4}\.\d{2}\.\d{2}\([SMTWtFs]\)(?:am|pm)\d{2}:\d{2}\.\d{2}\s*$/, '').trim();
  }
  const we = new vscode.WorkspaceEdit();
  we.replace(doc.uri, span.range, span.body);
  await vscode.workspace.applyEdit(we);
  const start = span.range.start;
  const sel = (span.kind === 'heading')
    ? new vscode.Selection(start, start)
    : new vscode.Selection(start, new vscode.Position(start.line, start.character + span.body.length));
  editor.selection = sel;
  await vscode.window.showTextDocument(doc, { viewColumn: editor.viewColumn, preserveFocus: false, selection: sel });
  vscode.window.setStatusBarMessage('Format: 解除しました', 1500);
}
// v0.9.999127(俊克): ハイライト/取消線の記法を組み立てる(insertFormatTemplateと同形式)。↻リングのライブ再適用用。
function buildInlineFmt(doc, kind, body, fg, bg) {
  const wrap = MEOS_BLOCK_COMMENT_LANGS.has(doc.languageId);
  const prefix = (kind === 'highlight') ? '=={' : '~~{';
  const close = (kind === 'highlight') ? '}==' : '}~~';
  const def = (kind === 'strike') ? { fg: '赤', bg: '' } : { fg: '赤', bg: '黄' };
  const FG = (fg && String(fg).trim()) ? String(fg).trim() : def.fg;
  const BG = (typeof bg === 'string') ? bg.trim() : def.bg;
  const spec = '(' + FG + '/' + BG + ')//[]tip=';
  const openPart = wrap ? ('/* ' + prefix + ' */ ') : prefix;
  const tailPart = wrap ? (' /* ' + spec + close + ' */') : (spec + close);
  const pad = wrap ? '' : ' ';
  return { full: openPart + pad + body + pad + tailPart, bodyOffset: openPart.length + pad.length, bodyLen: body.length };
}

// {* ▼mCN=0867_BOOKMARK // 🔖 ワンブックマーク(最大3個・安全装置) v0.9.715 (📊⊕0+0D0W) *}
// 「場所の記憶」。最大3個のしおりを装飾🔖のみで表示(ソースに1mmも書かない)。globalStateにURIキーで永続。
// ★戻る(cycle)と消す(remove)を分離: cycleは大事な場所へ巡回ジャンプ／removeはカーソル行のしおりだけ消す
