  pop.addEventListener('click',function(ev){const r=ev.target&&ev.target.closest?ev.target.closest('.toc-child-row'):null;if(!r)return;const _k=r.getAttribute('data-key');if(_k){vscode.postMessage({type:'jumpToMembraneKey',key:_k});}else{const ln=parseInt(r.getAttribute('data-line'),10);if(Number.isFinite(ln))vscode.postMessage({type:'jumpLine',line:ln});}window.closeTocChildPop();});
