const FMT_BG=[['なし',''],['赤','#e13737'],['橙','#ffa028'],['黄','#ffe600'],['緑','#37a546'],['青','#3c7deb'],['紫','#be82f5'],['桃','#ff82c8'],['紺','#192387'],['水','#2dbef0'],['ワイン','#96232d']];
