function placeFmtPop(){if(!fmtPop||!fmtPop.classList.contains('on'))return;requestAnimationFrame(()=>{const h=fmtPop.offsetHeight||70,w=fmtPop.offsetWidth||130;const left=Math.min(Math.max(6,fmtPopCenterX-w/2),window.innerWidth-w-6);fmtPop.style.left=left+'px';fmtPop.style.top=Math.max(6,fmtPopBottom-h)+'px';});}
/* v0.9.999143(俊克): 色ピッカー/リング適用のスロット不一致を解消。actionable時は「今ボタンが表示している幅wのスロット」を返し、ピッカーの編集先とリングの適用先を一致させる(見出しで色が適用されない真因)。 */function fmtCurSpec(kind){if(window.__fmtActionable&&window.__fmtActionable[kind]){const r=(window.__fmtRing&&window.__fmtRing[kind])||0;const baseW=(window.__fmtBaseW&&window.__fmtBaseW[kind])||2;const w=(r===0)?baseW:(((baseW-1+r)%3)+1);return (kind==='heading')?fmtHeadingColors[w]:(kind==='highlight')?fmtHlSlots[w-1]:fmtStSlots[w-1];}return fmtSpec[kind];}
function renderFmtPop(){if(!fmtPop)return;const spec=fmtCurSpec(fmtPopKind);let html='';if(fmtPopCh){const ch=fmtPopCh,list=ch==='fg'?FMT_FG:FMT_BG,cur=spec[ch];html+='<div class="fmt-pop-head">'+fmtChLabel(fmtPopKind,ch)+'</div><div class="fmt-grid">'+list.map(([w,hex])=>{const active=(w==='なし')?!cur:(w===cur);return '<button class="fmt-swatch'+(active?' active':'')+'" data-color="'+w+'" title="'+(FMT_EN[w]||w)+', '+w+'"><span class="fmt-ball'+(hex?'':' none')+'" style="background:'+(hex||'transparent')+'"></span></button>';}).join('')+'</div>';}const fgD=(fmtPopCh&&fmtPopCh!=='fg')?' dim':'',bgD=(fmtPopCh&&fmtPopCh!=='bg')?' dim':'';html+='<div class="fmt-slots"><button class="fmt-slot'+(fmtPopCh==='fg'?' active':'')+fgD+'" data-ch="fg" title="'+fmtChLabel(fmtPopKind,'fg')+(spec.fg?' — '+(FMT_EN[spec.fg]||spec.fg)+', '+spec.fg:'')+'"><span class="fmt-ball" style="background:'+fmtHexFg(spec.fg)+'"></span></button><span class="fmt-slot-sep">/</span><button class="fmt-slot'+(fmtPopCh==='bg'?' active':'')+bgD+'" data-ch="bg" title="Background color'+(spec.bg?' — '+(FMT_EN[spec.bg]||spec.bg)+', '+spec.bg:' — none, なし')+'"><span class="fmt-ball'+(spec.bg?'':' none')+'" style="background:'+fmtHexBg(spec.bg)+'"></span></button></div>';fmtPop.innerHTML=html;placeFmtPop();}
function openFmtPop(kind,anchor){fmtPopKind=kind;fmtPopCh=null;const r=anchor.getBoundingClientRect();fmtPopCenterX=r.left+r.width/2;fmtPopBottom=r.top-6;fmtPop.classList.add('on');renderFmtPop();}
