if(fmtStrike)fmtStrike.addEventListener('click',()=>{if(window.__fmtActionable.strike){const r=window.__fmtRing.strike||0;window.__fmtCyclingKind='strike';window.__fmtCyclingUntil=Date.now()+500;if(r===0){vscode.postMessage({type:'fmtCycle',kind:'strike',ring:0});}else{const baseW=window.__fmtBaseW.strike||2;const w=((baseW-1+r)%3)+1;const sp=fmtStSlots[w-1];window.__fmtBaseW.strike=w;window.__fmtRing.strike=0;window.__fmtWasDeco.strike=true;vscode.postMessage({type:'fmtCycle',kind:'strike',ring:w,fg:sp.fg,bg:sp.bg});window.__renderFmtRing('strike');}return;}vscode.postMessage({type:'insertFormat',kind:'strike',fg:fmtSpec.strike.fg,bg:fmtSpec.strike.bg});if((Number(document.body.dataset.phase||1))>=4){const _w=[1,2,3][fmtStIdx];window.__fmtActionable.strike=true;window.__fmtBaseW.strike=_w;window.__fmtRing.strike=0;window.__fmtWasDeco.strike=true;window.__fmtCyclingKind='strike';window.__fmtCyclingUntil=Date.now()+500;window.__renderFmtRing('strike');}});
if(fmtHeading)fmtHeading.addEventListener('click',()=>{if(window.__fmtActionable.heading){const r=window.__fmtRing.heading||0;window.__fmtCyclingKind='heading';window.__fmtCyclingUntil=Date.now()+500;if(r===0){vscode.postMessage({type:'fmtCycle',kind:'heading',ring:0});}else{const baseW=window.__fmtBaseW.heading||2;const w=((baseW-1+r)%3)+1;const hc=fmtHeadingColors[w];window.__fmtBaseW.heading=w;window.__fmtRing.heading=0;window.__fmtWasDeco.heading=true;vscode.postMessage({type:'fmtCycle',kind:'heading',ring:w,fg:hc.fg,bg:hc.bg,level:w});window.__renderFmtRing('heading');}return;}vscode.postMessage({type:'insertFormat',kind:'heading',fg:fmtSpec.heading.fg,bg:fmtSpec.heading.bg,level:fmtHeadingLevel});if((Number(document.body.dataset.phase||1))>=4){window.__fmtActionable.heading=true;window.__fmtBaseW.heading=fmtHeadingLevel;window.__fmtRing.heading=0;window.__fmtWasDeco.heading=true;window.__fmtCyclingKind='heading';window.__fmtCyclingUntil=Date.now()+500;window.__renderFmtRing('heading');}});
