const fmtHeadCycle=document.getElementById('fmt-head-cycle');if(fmtHeadCycle)fmtHeadCycle.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();window.__fmtTipSuppress=true;if(typeof hideTocTip==='function')hideTocTip();if(window.__fmtActionable.heading){window.__fmtRing.heading=((window.__fmtRing.heading||0)+1)%4;window.__fmtCyclingKind='heading';window.__fmtCyclingUntil=Date.now()+500;window.__renderFmtRing('heading');return;}fmtHeadingLevel=(fmtHeadingLevel%3)+1;fmtSpec.heading=fmtHeadingColors[fmtHeadingLevel];const hh='#'.repeat(fmtHeadingLevel);if(fmtHeading){fmtHeading.textContent=hh;fmtHeading.setAttribute('data-tip','Heading (H'+fmtHeadingLevel+') | '+hh+'[ text (text/bg)//tip ]'+hh+' — ▾ picks color · ↻ cycles # → ## → ###');}renderFmtBtnColors();pushFmt();if(fmtPop&&fmtPop.classList.contains('on')&&fmtPopKind==='heading')renderFmtPop();});
