const TIP_GAP_PX=44;
function showTocTip(ev){if(!tocTooltip)return;if(window.__tocChildOpen)return;/* v1.0.1(俊克 改良1): Format↻を1回押したらプリセット選択中はtip抑制(見出しtipが左に伸びて邪魔)。Format行を離れたら解除→次回また1回だけ出る。 */if(window.__fmtTipSuppress&&ev&&ev.target&&ev.target.closest&&ev.target.closest('#format-tools')){hideTocTip();return;}/* v0.9.999123: 副メニュー表示中はtip抑止 */if(window.__headWrapUntil&&Date.now()<window.__headWrapUntil){hideTocTip();return;}/* v3.0.4(俊克 改良1): 表の▾メニュー(table-pop)が開いている間はメニュー外要素(表ボタン/▾自身/他の書式ボタン)のtipを出さない=開いたメニューを覆わない。メニュー内の項目tipは.bm-pop.on分岐が担当。 */{var _tpo=document.getElementById('table-pop');if(_tpo&&_tpo.classList.contains('on')&&!(ev&&ev.target&&ev.target.closest&&ev.target.closest('#table-pop'))){hideTocTip();return;}}if(window.__refDeciding){hideTocTip();return;}/* v0.9.99988: セグメント決定中はtip抑制(俊克) *//* v0.9.805: H-TOC項目のコメント編集中(toc-valueにフォーカス)はtip非表示=編集の邪魔をしない。 */{const ae=document.activeElement;if(ae&&ae.classList&&ae.classList.contains('toc-value')){hideTocTip();return;}}
/* v2.0.37(俊克): 基準点入力枠(#dw-base-input)が開いている間はホバーtipを抑止=入力枠のtitle「Base point…」が赤ヒント(#dw-hint)を上書きする件を根治。 */
{var _dwbi=document.getElementById('dw-base-input');if(_dwbi&&_dwbi.classList.contains('on')){hideTocTip();return;}}const el=(ev.target&&ev.target.closest)?ev.target.closest('[data-tip],[title]'):null;/* v0.9.712: native title を data-tip に遅延移行(ネイティブtipを抑止し共通の左伸ばしtipに一本化)。JSが.titleを再設定しても次のhoverで反映。 */if(el&&el.hasAttribute('title')){const tt=el.getAttribute('title');if(tt)el.setAttribute('data-tip',tt);el.removeAttribute('title');}const t=el?el.getAttribute('data-tip'):'';if(!t){hideTocTip();return;}/* v0.9.691: split the " | " separated parts (Created/Checked/Cite) onto separate lines for readability (俊克 am11:38). 改行は String.fromCharCode(10) で安全に(テンプレートリテラル回避)。CSSは white-space:pre-line。 */tocTooltip.textContent=String(t).split(' | ').join(String.fromCharCode(10));/* v0.9.686: grow the tip LEFT from the cursor (Me Dock sits at the screen's right edge, so a right-growing tip clips); wrap to 2+ lines. Anchor the tip's RIGHT edge ~12px left of the cursor. */tocTooltip.style.display='block';tocTooltip.style.maxWidth='';tocTooltip.style.width='';/* v1.0.7: 既定幅(CSS 260px)に戻す。bm-pop.on分岐だけが左逃がし用に一時的に幅を詰める。v1.0.23: widthも毎回リセット(バッジ分岐が固定widthを置くため)。 *//* v0.9.99981(改良1 俊克): 開いているプルダウン(.bm-pop.on)内の項目tipは、マウスX追従をやめて ポップアップ左端に接した固定位置に出す(メニューを隠さない)。縦は項目に合わせる。 */{const _popEl=el.closest&&el.closest('.bm-pop');if(_popEl&&_popEl.classList.contains('on')){const pr=_popEl.getBoundingClientRect();/* v1.0.7(俊克 改良2): 大ポップアップ(参照メニュー等)のtipは下に落ちてボタンを隠しがち→左に余地(≥120px)があれば幅をその余地に詰めて左へ逃がす。Me Dockが狭く左に余地が無い時だけ従来の上/下フォールバック。 */const avail=pr.left-6;if(avail>=120){tocTooltip.style.maxWidth=Math.min(260,avail)+'px';const h=tocTooltip.offsetHeight||20;tocTooltip.style.left='auto';tocTooltip.style.right=(window.innerWidth-pr.left+1)+'px';let top=pr.top;if(top+h>window.innerHeight-2)top=window.innerHeight-h-2;if(top<2)top=2;tocTooltip.style.top=top+'px';}else{tocTooltip.style.maxWidth='';const tw=tocTooltip.offsetWidth||160,h=tocTooltip.offsetHeight||20;tocTooltip.style.right='auto';let left=pr.left;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=pr.top-h-1;if(top<2)top=pr.bottom+1;tocTooltip.style.top=top+'px';}return;}}/* v0.9.769: タブのtipは常に"上空"に出す(ドラッグ中にドロップ位置を隠さないため)。タブ左に揃え、上に余地が無ければ下。 */const _tabEl=el.closest&&el.closest('.toc-tab');if(_tabEl){const r=_tabEl.getBoundingClientRect();const tw=tocTooltip.offsetWidth||120,h=tocTooltip.offsetHeight||20;tocTooltip.style.right='auto';let left=r.left;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=r.top-h-6;if(top<2)top=r.bottom+6;tocTooltip.style.top=top+'px';return;}/* v0.9.829: Mepyの挨拶tipは必ず顔の外に(俊克 am03:43)。顔(membrane-visual)の上に中央寄せ・上に余地が無ければ下。 *//* v0.9.881: Format色ピッカー(スウォッチ/スロット)のtipは要素の真上に近接表示(離れすぎ対策・俊克 6/15 pm00:24)。 */const _fmtEl=el.closest&&el.closest('#fmt-pop');if(_fmtEl){const r=el.getBoundingClientRect();const tw=tocTooltip.offsetWidth||80,h=tocTooltip.offsetHeight||18;tocTooltip.style.right='auto';let left=r.left+(r.width-tw)/2;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=r.top-h-5;if(top<2)top=r.bottom+5;tocTooltip.style.top=top+'px';return;}/* v1.0.2(俊克): Format3兄弟(==/~~/##)とその↻/▾のtipは左伸ばしでなくボタンの真上に中央寄せで出す(見出し↻のtipが左に伸びて##の左を覆う件)。 *//* v1.0.21(俊克 改良2): 栞3兄弟の右肩F/HバッジのtipはFormat3兄弟と同じくボタンの真上に中央寄せで出す(左伸ばしをやめる)。 *//* v1.0.24(俊克 改良1): 2ボタン一体化(split button)クラスタ=主ボタン/▾/右肩バッジのtipは全て横幅固定(200px)で真上に中央寄せ=左伸ばしで隣のボタンを覆わない。v1.0.23の.bm-f-badge限定を.bm-splitへ拡大。 *//* v2.0.8(俊克): 合体ボタン(.tt-split)のtipは、栞bm-splitの固定幅200px右アンカー(左に押し出され見切れ→ほぼ空白)ではなく、ホバー要素の真上に内容幅で中央寄せ表示。 *//* v3.1.18(俊克 改良3): Me Dockズームのボタン群(.mz-split)のtipは、ホバー要素の真上に中央寄せで出す(左伸ばしで隣を覆わない・バランス改善)。 */const _mzEl=el.closest&&el.closest('.mz-split');if(_mzEl){const r=el.getBoundingClientRect();const cr=_mzEl.getBoundingClientRect();/* v3.1.22(俊克 v3.1.21 NG): tip幅を位置に依存させない2パス測定。Me Dockは画面右端に貼り付くので、left指定のみのfixed要素はshrink-to-fitが「leftから右端までの余地」に潰れ→縦長1語/行になり、次のmousemoveで測り直す度に左へドリフトしていた。pass1=右アンカー(right:2px)で左方向に十分な余地を与え自然幅natWを測る(位置非依存で毎回一定)→pass2=natWを固定幅にしてホバー要素の真上に中央寄せ=潰れ/ドリフト根治。 */tocTooltip.style.width='';tocTooltip.style.maxWidth='260px';tocTooltip.style.left='auto';tocTooltip.style.right='2px';const natW=tocTooltip.offsetWidth||120;tocTooltip.style.right='auto';tocTooltip.style.width=natW+'px';const h=tocTooltip.offsetHeight||18;let left=r.left+(r.width-natW)/2;if(left+natW>window.innerWidth-2)left=window.innerWidth-natW-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=cr.top-h-6;if(top<2)top=cr.bottom+6;tocTooltip.style.top=top+'px';return;}const _ttSplitEl=el.closest&&el.closest('.tt-split');if(_ttSplitEl){const r=el.getBoundingClientRect();/* v2.0.26(俊克 改良3): 縦位置は個々の要素でなく合体ボタン容器(=ボタン行)の上端基準に統一。Ⓝ角バッジはボタン下端にはみ出て低いので、そのbottom基準ではtipがボタンに被る→容器topに揃えTodayのtipと同じ高さに(ボタンが見える)。 */const cr=_ttSplitEl.getBoundingClientRect();const tw=tocTooltip.offsetWidth||80,h=tocTooltip.offsetHeight||18;tocTooltip.style.right='auto';let left=r.left+(r.width-tw)/2;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=cr.top-h-6;if(top<2)top=cr.bottom+6;tocTooltip.style.top=top+'px';return;}
const _bmSplitEl=el.closest&&el.closest('.bm-split');if(_bmSplitEl){/* v1.0.26(俊克 改良1): 栞/参照のプルアップメニューが開いている間はsplitクラスタ(主/▾/バッジ)のtipを出さない=メニューを覆わない。メニュー内の項目tipは別分岐(.bm-pop.on)が担当。 */if(document.querySelector('.bm-pop.on')){hideTocTip();return;}/* v1.0.25(俊克 改良1): tipの右端をそのsplit(2ボタン一体化)の右端に一致させる=右端アンカー。中央寄せ+innerWidthクランプはwebviewのinnerWidth誤差で右にはみ出るため廃止。getBoundingClientRectの実座標でright指定=はみ出さない。 */var FBW=200;var _tt=String(t);/* v1.0.27(俊克): 飛び先(warp)行=センチネルU+0001付きセグメントを色付き(参照=青/栞=赤)・折り返さず1行で最下部に。tip幅はwarp行に合わせて自動調整(1行に収める)。 */if(_tt.indexOf(String.fromCharCode(1))>=0){var _esc=function(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};var _wc=el.closest('.bm-pending-split')?'#2563eb':(el.closest('.home-split')?'#16a34a':'#dc2626');var _sg=_tt.split(' | ');var _ha=[];var _wtxt='';_sg.forEach(function(s){if(s.charCodeAt(0)===1){_wtxt=s.slice(1);_ha.push('<div style="white-space:nowrap;color:'+_wc+';font-weight:800;margin-top:3px">'+_esc(_wtxt)+'</div>');}else{_ha.push('<div>'+_esc(s)+'</div>');}});tocTooltip.innerHTML=_ha.join('');var _cs=getComputedStyle(tocTooltip);var _ms=document.createElement('span');_ms.style.cssText='position:absolute;visibility:hidden;white-space:nowrap;font-weight:800';_ms.style.fontSize=_cs.fontSize;_ms.style.fontFamily=_cs.fontFamily;_ms.textContent=_wtxt;document.body.appendChild(_ms);var _need=_ms.offsetWidth;document.body.removeChild(_ms);FBW=Math.min(460,Math.max(200,_need+16));}const r=_bmSplitEl.getBoundingClientRect();/* v2.0.19(俊克): 右端アンカーだと左寄せ配置(4兄弟)のsplitでtipが画面左端をはみ出して見切れる→左座標をビューポート内にクランプ(右端に寄せつつ、左に足りなければ右へ) */tocTooltip.style.right='auto';tocTooltip.style.maxWidth=FBW+'px';tocTooltip.style.width=FBW+'px';var _tl=r.right-FBW;if(_tl+FBW>window.innerWidth-2)_tl=window.innerWidth-FBW-2;if(_tl<2)_tl=2;tocTooltip.style.left=_tl+'px';const h=tocTooltip.offsetHeight||20;let top=r.top-h-6;if(top<2)top=r.bottom+6;tocTooltip.style.top=top+'px';return;}const _fmtToolEl=el.closest&&el.closest('#format-tools');if(_fmtToolEl){const r=el.getBoundingClientRect();const tw=tocTooltip.offsetWidth||120,h=tocTooltip.offsetHeight||20;tocTooltip.style.right='auto';let left=r.left+(r.width-tw)/2;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=r.top-h-6;if(top<2)top=r.bottom+6;tocTooltip.style.top=top+'px';return;}const _mepyEl=el.closest&&(el.closest('.mepy-hello')||el.closest('#membrane-visual'));if(_mepyEl){/* v3.1.28(俊克 個別修正): mepy(Nice to meet Me)は本家VS Codeでも正位置=基準の membrane-visual のrectだけは本家でも信頼できる。faceボックス内の要素(color-btn=「Membrane color」/me-choice等)は自前rectが本家zoomで大きく狂うので、mepyと同じ membrane-visual 基準(真上・中央)に乗せる。 */const face=document.getElementById('membrane-visual');const fr=(face||_mepyEl).getBoundingClientRect();const tw=tocTooltip.offsetWidth||120,h=tocTooltip.offsetHeight||20;tocTooltip.style.right='auto';let left=fr.left+(fr.width-tw)/2;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=fr.top-h-8;if(top<2)top=fr.bottom+8;tocTooltip.style.top=top+'px';return;}const _baEl=el.closest&&el.closest('.big-action,.nav-center-btn,.me-flip-btn,.eof-badge,.line-btn,.time-machine-trigger,.time-machine-clear,.tm-world-row,.bird-ev-label,.nss-head,.nss-mark,.nav-scroll,.me-nav-switch,.head-nav');if(_baEl){/* v3.1.32-33(俊克): big-action及びNavigate行(Time Machine/Bird-EV/ノブ)のtipは、要素自身の子 ::after(CSSだけ)で表示=同じzoom文脈で本家/VSCodium両方自動的に正位置。JSの共有fixed tooltipは出さない(座標計算を捨てる)。 */hideTocTip();return;}const rowEl=(el.closest&&el.closest('.fixed-toc-item,.toc-pin'))||el;/* v3.1.27(俊克の慧眼): mepy(Nice to meet Me)は本家VS Codeでも正位置=基準の membrane-visual が position:relative。崩れる Shed/Encrypt/Navigate は全て position:static。→本家Chromiumが CSS zoom 下で static 要素の getBoundingClientRect を fixed(tooltip)と別座標系で返すのが真因。測定の一瞬だけ対象を position:relative(オフセット無し=見た目1pxも動かない)にして、mepyと同じ座標系で測る。v3.1.26のキャリブレーションは前提が誤りだったので撤去。 */var _mtgt=(rowEl&&rowEl.style)?rowEl:el;var _msp=_mtgt.style.position;_mtgt.style.position='relative';const rect=_mtgt.getBoundingClientRect();_mtgt.style.position=_msp;const tw=tocTooltip.offsetWidth||120;const h=tocTooltip.offsetHeight||20;if(rect.left-TIP_GAP_PX-tw<4){/* 左端の細い要素は左伸ばしだと見切れる→上に載せ右方向へ。 */tocTooltip.style.right='auto';let left=rect.left;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=rect.top-h-4;if(top<2)top=rect.bottom+4;if(top+h>window.innerHeight-2)top=window.innerHeight-h-2;tocTooltip.style.top=top+'px';}else{/* 通常: 要素の右端から左伸ばし・行の上端に合わせる。 */tocTooltip.style.right='auto';let left=rect.right-tw;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=rect.top+1;if(top<2)top=2;if(top+h>window.innerHeight-2)top=window.innerHeight-h-2;tocTooltip.style.top=top+'px';}}
function hideTocTip(){if(tocTooltip)tocTooltip.style.display='none';}
/* v0.9.712: 全tip統一。webview全体で mousemove を拾い、data-tip / native title を持つ最近接要素に
   共通の左伸ばしtipを出す(showTocTip内で title→data-tip 遅延移行)。個別リスナ(fixedTocBody/format-tools)は廃止し1本化。 */
document.addEventListener('mousemove',showTocTip);
document.addEventListener('mouseleave',hideTocTip);
/* v0.9.774: H-TOCスクロール中はtipを隠す(タブD&Dと同じ発想・俊克 am04:20)。スクロール後にマウスを動かせば再表示。 */
if(fixedTocBody)fixedTocBody.addEventListener('scroll',hideTocTip,{passive:true});

if(toggleEditorToc)toggleEditorToc.addEventListener('click',()=>vscode.postMessage({type:'toggleEditorToc'}));
if(tocMoveUp)tocMoveUp.addEventListener('click',()=>moveSelectedToc(-1));
if(tocMoveDown)tocMoveDown.addEventListener('click',()=>moveSelectedToc(1));/* v3.6.6(俊克): Hyper IDXの🖼=現在の膜の画像リンク行へワープ+ビューア表示(長い膜でも現場へ一発)。 */var idxGotoImage=document.getElementById('idx-goto-image');if(idxGotoImage)idxGotoImage.addEventListener('click',()=>vscode.postMessage({type:'gotoMembraneImage'}));
if(tocAdd)tocAdd.addEventListener('click',()=>vscode.postMessage({type:'duplicateTocItem',line0:selectedTocLine0}));
// v0.9.565: delete-selected-item button. User v0.9.564_0338 request:
// 「選択した目次項目を削除する[-]ボタンを追加して下さい」.
if(tocDelItem)tocDelItem.addEventListener('click',()=>{
  if(selectedTocLine0===null||selectedTocLine0===undefined){return;}
  vscode.postMessage({type:'deleteTocItem',line0:selectedTocLine0});
});
// v0.9.549 Phase C-1: Hyper TOC tab bar interactions (delegated via tocTabRow because
// inner content is re-rendered every snapshot).
if(tocTabRow){
  tocTabRow.addEventListener('click',ev=>{
    const target=ev.target;
    if(!target)return;
    if(target.id==='toc-tab-add'){vscode.postMessage({type:'duplicateHyperTocTab'});return;}
    if(target.id==='toc-tab-del'){
      // Show confirm panel; the actual delete fires on yes click.
      if(tocTabConfirm){tocTabConfirm.classList.add('on');if(tocTabConfirmMsg){const activeTab=tocTabRow.querySelector('.toc-tab.active');tocTabConfirmMsg.textContent='Delete tab "'+((activeTab?activeTab.textContent:'')||'Hyper TOC')+'"?';}}
      return;
    }
    const tab=target.closest&&target.closest('.toc-tab');
    if(tab){const idx=Number(tab.getAttribute('data-tab-idx'));if(!isNaN(idx))vscode.postMessage({type:'switchHyperTocTab',idx});}
  });
  // v0.9.768: タブのドラッグ並べ替え(HTML5 DnD・イベント委譲。innerHTML再生成されてもtocTabRowは残る)。
  let _dragTabIdx=null;
  let _pendingTo=null;       /* v0.9.772: dragoverで「今表示している挿入線」の対象idx。 */
  let _dropHandled=false;    /* v0.9.773: dropが発火したか。 */
  function _clearDropMarks(){tocTabRow.querySelectorAll('.toc-tab.dragging,.toc-tab.drop-left,.toc-tab.drop-right').forEach(el=>el.classList.remove('dragging','drop-left','drop-right'));}
  /* v0.9.773: 「見えている挿入線(_pendingTo)」に入れる。dropはパネル外で離すと発火しないので、必ず発火するdragendでも確定する(=どこで離しても線が出ていれば移動)。 */
  function _commitTabReorder(){if(_dragTabIdx!==null&&_pendingTo!==null&&!isNaN(_dragTabIdx)&&!isNaN(_pendingTo)&&_dragTabIdx!==_pendingTo){vscode.postMessage({type:'reorderHyperTocTab',from:_dragTabIdx,to:_pendingTo});}}
  /* v0.9.770: ポインタが直接タブ上に無くてもX座標で最寄りのタブを解決(右端を越えたら最後のタブ=末尾へ移動可能に)。 */
  function _resolveDropTab(ev){const direct=ev.target&&ev.target.closest&&ev.target.closest('.toc-tab');if(direct)return direct;const tabs=tocTabRow.querySelectorAll('.toc-tab');if(!tabs.length)return null;const x=ev.clientX,first=tabs[0],last=tabs[tabs.length-1];if(x>=last.getBoundingClientRect().right)return last;if(x<=first.getBoundingClientRect().left)return first;let best=first;for(const t of tabs){if(x>=t.getBoundingClientRect().left)best=t;}return best;}
  tocTabRow.addEventListener('dragstart',ev=>{const tab=ev.target&&ev.target.closest&&ev.target.closest('.toc-tab');if(!tab){return;}_dragTabIdx=Number(tab.getAttribute('data-tab-idx'));_pendingTo=null;_dropHandled=false;if(ev.dataTransfer){ev.dataTransfer.effectAllowed='move';try{ev.dataTransfer.setData('text/plain',String(_dragTabIdx));}catch(_){}}tab.classList.add('dragging');if(typeof hideTocTip==='function')hideTocTip();/* v0.9.769: ドラッグ中はtipを隠してドロップ位置を見えるように。 */});
  /* v0.9.770: dragover/drop は H-TOCパネル全体(fixedToc)で受ける。右はopsボタンが行き過ぎを拾うが左はタブ左に
     要素が無く tocTabRow の外に出て発火しなかった非対称を解消。_resolveDropTab がX座標で先頭/末尾/最寄りに解決。 */
  const _dropZone=(typeof fixedToc!=='undefined'&&fixedToc)?fixedToc:tocTabRow;
  _dropZone.addEventListener('dragover',ev=>{if(_dragTabIdx===null)return;const tab=_resolveDropTab(ev);if(!tab)return;ev.preventDefault();if(ev.dataTransfer)ev.dataTransfer.dropEffect='move';tocTabRow.querySelectorAll('.toc-tab.drop-left,.toc-tab.drop-right').forEach(el=>el.classList.remove('drop-left','drop-right'));const overIdx=Number(tab.getAttribute('data-tab-idx'));/* v0.9.769: 右へ移動なら対象の右側、左へ移動なら左側に太線(実際の挿入位置と一致)。 */if(overIdx!==_dragTabIdx){tab.classList.add(overIdx>_dragTabIdx?'drop-right':'drop-left');_pendingTo=overIdx;}else{_pendingTo=null;}});
  _dropZone.addEventListener('drop',ev=>{if(_dragTabIdx===null)return;ev.preventDefault();_dropHandled=true;_commitTabReorder();_dragTabIdx=null;_pendingTo=null;_clearDropMarks();});
  /* v0.9.773: dropがパネル外で発火しなくても、必ず発火するdragendで「見えていた線」に確定する。 */
  tocTabRow.addEventListener('dragend',()=>{if(!_dropHandled)_commitTabReorder();_dragTabIdx=null;_pendingTo=null;_dropHandled=false;_clearDropMarks();});
}
