    if (message && message.type === 'bookmarkTogglePending') { await referenceIssue(getMeDockTargetEditor() || vscode.window.activeTextEditor); return; } // v0.9.99970: 💤ボタン=参照符の発行に差替(段5・💤統合)。旧bookmarkTogglePending(仮想保留)はレガシー▾メニュー専用に降格
    if (message && message.type === 'bookmarkRemovePending') { await bookmarkRemovePending(getMeDockTargetEditor() || vscode.window.activeTextEditor); return; } // v0.9.897: カーソル行の💤をResolve
